/** What each capability is, for a palette or a settings screen. */
export const CAPABILITY_INFO = {
    'agent.attention': { title: "Is this agent stuck", group: 'agent', kind: 'query', role: 'viewer', effects: [], doc: "Baselines are per binding and learned from its own history: thirty seconds is an eternity for a linter and a blink for a test suite, so a fixed threshold is wrong for everybody." },
    'agent.compare': { title: "Compare parallel runs", group: 'agent', kind: 'query', role: 'viewer', effects: [], doc: "Presents comparable facts; never ranks, scores or recommends. Judging requires understanding the code, and a plausible wrong recommendation about which branch to keep costs somebody real work." },
    'agent.connect': { title: "Connect a protocol agent", group: 'agent', kind: 'command', role: 'operator', effects: ['spawns_process'], doc: "Run an agent's own protocol server and fold its notifications into the session's event stream. Anything the adapter cannot map is reported by name rather than dropped." },
    'agent.hooks_install': { title: "Install omt's hooks", group: 'agent', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Without these, an agent's structured question — the tool call that offers options — never reaches omt, and a card that could have been answered on a phone is a prompt only the terminal can see." },
    'agent.hooks_plan': { title: "Plan a hook install", group: 'agent', kind: 'query', role: 'operator', effects: ['reads_fs'], doc: "The diff, before the write. omt edits a file the agent owns and somebody else may have written their own hooks into, so what changes is shown first." },
    'agent.interrupt': { title: "Interrupt an agent", group: 'agent', kind: 'command', role: 'operator', effects: ['writes_pty'], doc: "Stop an agent. For an agent with no protocol of its own this is the entire remote control surface." },
    'agent.offers': { title: "What an agent offers", group: 'agent', kind: 'query', role: 'viewer', effects: [], doc: "Slash commands, tools, models and the pending message queue, as the agent itself reported them. Never a list omt maintains: a completion popup offering a command the agent does not have is worse than none." },
    'agent.threads': { title: "List agent threads", group: 'agent', kind: 'query', role: 'viewer', effects: [], doc: "Every thread in a session — the main one and each subagent — with what it is doing and any card it raised." },
    'agent.wait': { title: "Wait for an agent", group: 'agent', kind: 'query', role: 'viewer', effects: [], doc: "The primitive that stops every script being a sleep loop. `blocked` is a state and matches at once; `interaction` is an edge and matches only a card that opens after the wait began." },
    'agent_rules.capture': { title: "Capture a screen for writing rules", group: 'agent_rules', kind: 'query', role: 'operator', effects: [], doc: "The screen and each named region of it. Rules written from memory are wrong in ways only a real screen finds: omt's own rule for Claude Code's permission prompt was written from memory and was wrong about the first screen anybody sees." },
    'agent_rules.explain': { title: "Explain a screen verdict", group: 'agent_rules', kind: 'query', role: 'operator', effects: [], doc: "Which rule won, where it looked, and what it concluded. A wrong answer that cannot be traced to a rule is one people argue about." },
    'agent_rules.import': { title: "Install a rule set", group: 'agent_rules', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Only when asked, and only after the checks. omt never fetches, updates or applies a rule set on a timer or at startup: a matcher that runs against somebody's screen arrives because they decided, or not at all." },
    'agent_rules.inspect': { title: "Inspect a rule set", group: 'agent_rules', kind: 'query', role: 'operator', effects: [], doc: "What it would change, before anything changes. A rule set is a matcher that runs against whatever is on the screen, so installing one is an act rather than an update." },
    'audit.list': { title: "What has been done", group: 'audit', kind: 'query', role: 'admin', effects: [], doc: "Every call, with who made it and whether it worked. Refusals included: a log of only what succeeded answers the wrong question, because who *tried* to do what is most of what an audit is for." },
    'block.body': { title: "Read a block's output", group: 'block', kind: 'query', role: 'viewer', effects: [], doc: "The output of one command block, as styled lines. Paged, because a block can hold a whole test run and a phone asking for one over a slow link stalls." },
    'block.rerun': { title: "Re-run a command", group: 'block', kind: 'command', role: 'operator', effects: ['writes_pty'], doc: "Send a block's command to its session again. Refused for a block omt never saw the command of, because the alternative is scraping the screen for something that looks like a prompt." },
    'config.get': { title: "Read configuration", group: 'config', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "Resolved settings, each with the layer and file it came from — which is what makes a surprising value traceable." },
    'config.import': { title: "Import settings", group: 'config', kind: 'query', role: 'viewer', effects: [], doc: "Translate another terminal's settings into omt's, reporting what did not map rather than dropping it. A query: it says what the import would be, and writing it is a separate decision somebody makes." },
    'config.reload_class': { title: "When a setting takes effect", group: 'config', kind: 'query', role: 'viewer', effects: [], doc: "A setting that quietly waits for a restart is changed, nothing happens, and the conclusion is that the setting does not work." },
    'config.schema': { title: "List every setting", group: 'config', kind: 'query', role: 'viewer', effects: [], doc: "Every setting with its default, type and description — so a settings screen can be built without knowing the key names in advance. `config.get` reports what is set; this reports what could be." },
    'device.list': { title: "List paired devices", group: 'device', kind: 'query', role: 'operator', effects: [], doc: "Every device that has been let in, by the name it gave. Pairing mints a credential per device, and a credential nobody can see is one nobody revokes." },
    'device.rename': { title: "Rename a device", group: 'device', kind: 'command', role: 'admin', effects: ['writes_fs'], doc: "The label is the only thing distinguishing two devices in a list, and a list of three `iPhone`s is one nobody can revoke from — so renaming is part of revocation working." },
    'device.revoke': { title: "Revoke a device", group: 'device', kind: 'command', role: 'admin', effects: ['destructive'], doc: "Stop one device's credential working, leaving every other device alone. This is what makes a lost phone something somebody can act on." },
    'device.revoke_all': { title: "Revoke every other device", group: 'device', kind: 'command', role: 'admin', effects: ['destructive', 'writes_fs'], doc: "The `I lost a device and do not know which` button. Keeps the one asking, because revoking that too locks somebody out of the machine they were securing." },
    'doctor.report': { title: "Write a bug report", group: 'doctor', kind: 'query', role: 'operator', effects: ['reads_fs'], doc: "The diagnosis, the version and what the person was doing, as readable text they can check before sending. Nothing is uploaded: omt has no cloud, and a report somebody cannot read is one they have to trust blindly about their own machine." },
    'doctor.run': { title: "Diagnose this instance", group: 'doctor', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "Per-link diagnosis with a remedy on every failure. A check this build cannot perform is reported as not checked rather than as passing: an unrun check reported green is how a diagnosis stops somebody investigating the real problem." },
    'events.subscribe': { title: "Subscribe to events", group: 'events', kind: 'query', role: 'viewer', effects: [], doc: "Subscribe to the event stream." },
    'fanout.choose': { title: "Choose an arm", group: 'fanout', kind: 'command', role: 'operator', effects: [], doc: "Record which arm won, naming its branch. Merges nothing and deletes nothing: the losing worktrees are what you would look at to check the choice was right." },
    'fanout.start': { title: "Fan a prompt across agents", group: 'fanout', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Create a worktree per agent and record them as one fan-out. Every arm is reported, including any that could not be prepared." },
    'fanout.status': { title: "Fan-out status", group: 'fanout', kind: 'query', role: 'viewer', effects: [], doc: "Every arm of every fan-out, with its worktree, branch and state." },
    'fs.list': { title: "List files", group: 'fs', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "List a directory inside a workspace. Paths are workspace-relative and cannot escape it." },
    'fs.read': { title: "Read a file", group: 'fs', kind: 'query', role: 'viewer', effects: [], doc: "Read one chunk of a file. Chunked so a large file over a slow link can show progress and resume rather than restarting." },
    'fs.write': { title: "Write a file", group: 'fs', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Write one chunk of a file into a workspace. The file appears only once every chunk has arrived." },
    'git.diff': { title: "Git diff", group: 'git', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "Which files changed, with line counts. Staged and unstaged are separate answers." },
    'git.hunks': { title: "Diff a file", group: 'git', kind: 'query', role: 'viewer', effects: [], doc: "The changed lines of one file. `git.diff` reports which files changed; this is what changed in them. Returned as lines rather than rendered, because a terminal, a phone and a browser each want to draw it differently." },
    'git.status': { title: "Git status", group: 'git', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "Branch, divergence and working-tree state. Reads only — nothing here commits, checks out or fetches." },
    'help.render': { title: "Show help for a topic", group: 'help', kind: 'query', role: 'viewer', effects: [], doc: "A model rather than formatted text, so a phone and a terminal can render the same help differently without one of them parsing the other's layout." },
    'help.topics': { title: "Browse help", group: 'help', kind: 'query', role: 'viewer', effects: [], doc: "Derived from the catalog, not written beside it. Hand-written help is wrong the first time something is renamed and stays wrong, because nothing fails when it drifts." },
    'history.forget': { title: "Forget commands", group: 'history', kind: 'command', role: 'operator', effects: ['destructive'], doc: "The targeted counterpart to a store purge: somebody who typed a secret into a shell wants that line gone, not their whole history. Every run of a matching command goes, not only the most recent." },
    'history.query': { title: "Search command history", group: 'history', kind: 'query', role: 'viewer', effects: [], doc: "The instance-scoped query and the only implementation; `scope` narrows it. History exists where blocks exist, so a shell with no integration contributes nothing rather than guesses." },
    'identity.list': { title: "Who holds what", group: 'identity', kind: 'query', role: 'admin', effects: [], doc: "Every person this instance knows and the devices each holds. A credential answers whether a token may do something; this answers whose phone it is, which is what makes revoking somebody's access — rather than one token — expressible." },
    'identity.reauth_check': { title: "Does this need a fresh check", group: 'identity', kind: 'query', role: 'viewer', effects: [], doc: "A proof-of-presence timer, not an authorisation narrowing. Failing it means the device must show a human is holding it, and then it may do everything again." },
    'identity.revoke': { title: "Revoke a person's access", group: 'identity', kind: 'command', role: 'admin', effects: ['destructive'], doc: "Revoke every device one person holds, in one action. Doing it device by device means somebody who has left keeps whichever one was missed, and there is no moment at which their access is known to be gone." },
    'instance.catalog': { title: "List capabilities", group: 'instance', kind: 'query', role: 'viewer', effects: [], doc: "Every capability this instance offers." },
    'instance.info': { title: "Instance info", group: 'instance', kind: 'query', role: 'viewer', effects: [], doc: "Version and protocol of this instance." },
    'instance.metrics': { title: "How the instance is doing", group: 'instance', kind: 'query', role: 'operator', effects: [], doc: "Clients, sessions, calls and refusals. The health route says the process is up and says nothing else, which is not the same as knowing it is doing anything." },
    'instance.shutdown': { title: "Shut down", group: 'instance', kind: 'command', role: 'admin', effects: ['destructive'], doc: "Refuses while an agent is working or blocked, naming the sessions. A shutdown that takes an agent down mid-turn is the same loss an upgrade refuses to cause." },
    'interaction.list': { title: "List open questions", group: 'interaction', kind: 'query', role: 'viewer', effects: [], doc: "Every interaction waiting for a human, with whether omt can answer it from here and why not when it cannot." },
    'interaction.resolve': { title: "Answer a question", group: 'interaction', kind: 'command', role: 'operator', effects: [], doc: "Answer an open interaction. Exactly once: a second answer is refused with who won, and answerability comes from the deliverable rather than the state." },
    'invite.create': { title: "Invite another device", group: 'invite', kind: 'command', role: 'admin', effects: [], doc: "A fresh invite, so a second device can be paired from a device already paired. Without it the only invite is the one printed at startup, and adding a phone means restarting the instance everybody else is connected to." },
    'job.create': { title: "Schedule a job", group: 'job', kind: 'command', role: 'operator', effects: ['spawns_process'], doc: "Create a scheduled job, replacing any job of the same name. A missed window is skipped rather than caught up." },
    'job.list': { title: "List scheduled jobs", group: 'job', kind: 'query', role: 'viewer', effects: [], doc: "Scheduled jobs with when they fire and how many times each has failed in a row." },
    'keys.audit': { title: "Audit omt's own bindings", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "A registry nobody runs the defaults against documents a problem instead of preventing one." },
    'keys.cheatsheet': { title: "Keyboard reference", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "Every binding and every reserved key, generated from the keymap in force so it cannot go stale." },
    'keys.check_file': { title: "Check a keybinding file", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "A binding naming a capability that is not there parses, loads and does nothing — and the person who wrote it concludes their key is broken rather than their spelling." },
    'keys.conflicts': { title: "What a binding would break", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "`Conflicts with something` is not actionable — every chord collides somewhere. This says which program, what the key does there, and how badly it would be missed." },
    'keys.explain': { title: "Explain a key", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "`Not bound` and `bound, but the pane underneath owns it` look identical from the user's chair and have different fixes, so this says which." },
    'keys.flavour': { title: "vim or emacs bindings", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "A modal keymap governs omt's own surfaces only. It never governs a pane whose keys are passing through, which is what stops omt and an inner vim from contending over hjkl." },
    'keys.list': { title: "List every binding", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "In a stable order, so two calls can be compared. An unordered list makes a diff between two configurations unreadable." },
    'keys.registry': { title: "Known inner keymaps", group: 'keys', kind: 'query', role: 'viewer', effects: [], doc: "The registry is data, so a new agent CLI is a file rather than a release. This says how much of it is loaded." },
    'launch.preview': { title: "Preview a launch configuration", group: 'launch', kind: 'query', role: 'operator', effects: [], doc: "An agent is spawned with an argument vector, never by typing into a shell — a launch file is copied from a colleague and the prompt is the part people edit." },
    'layout.open': { title: "Open a layout", group: 'layout', kind: 'command', role: 'operator', effects: ['spawns_process'], doc: "Start several sessions as a layout, reporting the outcome of every pane rather than only that something failed." },
    'layout.restore': { title: "Restore a saved layout", group: 'layout', kind: 'query', role: 'operator', effects: ['reads_fs'], doc: "Keeps the panes that still exist and names the rest. Failing outright gives somebody nothing; keeping dead names gives them panes they have to close one by one." },
    'layout.save': { title: "Save this layout", group: 'layout', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "The tree and nothing else. Rects are a function of the tree and the screen, so saving them would restore a desktop layout onto a phone as a desktop layout." },
    'media.attach': { title: "Reference a file to an agent", group: 'media', kind: 'query', role: 'viewer', effects: [], doc: "Per-adapter, because one format applied to all of them is silently ignored by most — which looks exactly like an agent choosing not to read the file." },
    'media.clipboard': { title: "Copy to local clipboard", group: 'media', kind: 'command', role: 'operator', effects: [], doc: "OSC 52, wrapped for tmux when TERM says so. omt does not claim the copy succeeded: there is no acknowledgement to base that on." },
    'media.describe': { title: "Identify a blob", group: 'media', kind: 'query', role: 'viewer', effects: [], doc: "What a blob is, from its bytes rather than from a filename somebody supplied. A name is a claim; the bytes are the evidence, and writing an executable as a `.png` is what trusting the claim allows." },
    'media.get': { title: "Fetch a blob", group: 'media', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "By digest, which is the only name a blob has. There is no path to traverse because there is no path." },
    'media.list': { title: "List blobs", group: 'media', kind: 'query', role: 'operator', effects: [], doc: "A landing zone nobody can see the contents of is one that has quietly become the place things live." },
    'media.materialize': { title: "Write a blob to a path", group: 'media', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Under omt's managed root, never inside the workspace: an attachment written into the repository is an unreviewed file from a phone sitting in somebody's working tree." },
    'media.paste_tier': { title: "How paste reaches this machine", group: 'media', kind: 'query', role: 'viewer', effects: [], doc: "A tier is never claimed without a positive handshake. `Probably` means a paste that silently does nothing, and no way for the user to tell whether they mis-copied or omt mis-guessed." },
    'media.put': { title: "Upload a blob", group: 'media', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "The type is sniffed here and never taken from the sender. A sender that names its own content type decides how the receiver treats it." },
    'migrate.tmux_preview': { title: "Preview a tmux config", group: 'migrate', kind: 'query', role: 'operator', effects: ['reads_fs'], doc: "Every directive comes back classified, including the ones omt cannot map. A migration that silently drops a third of somebody's bindings fails without ever reporting an error." },
    'onboarding.disclosures': { title: "Advanced features", group: 'onboarding', kind: 'query', role: 'viewer', effects: [], doc: "Every trigger is something the user produced, and every feature is mentioned at most once. Advocacy for a feature somebody has not yet needed spends attention omt will want later." },
    'onboarding.dismiss_hints': { title: "Stop showing tips", group: 'onboarding', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Permanent. Somebody who turns tips off and is asked again next week has been told their answer did not count." },
    'onboarding.hint_state': { title: "Show the next tip", group: 'onboarding', kind: 'query', role: 'viewer', effects: [], doc: "At most one hint is ever offered. Six tips on a first run teach nobody six things; they teach that omt interrupts." },
    'open.click': { title: "Who owns this click", group: 'open', kind: 'query', role: 'viewer', effects: [], doc: "When the program in the pane has mouse reporting on, every press is its input. A multiplexer that swallows clicks so its own link handler can run has broken vim, and no link feature is worth that." },
    'open.recognize': { title: "Find links and paths", group: 'open', kind: 'query', role: 'viewer', effects: [], doc: "Paths, URLs and file:line references on a line of output, with their offsets — so a client can make them tappable without inventing its own pattern." },
    'open.remote_discard': { title: "Discard a mirrored file", group: 'open', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Unpins the blob so the sweeper can take it. Discarding something already gone is reported, not an error — a retry after a lost acknowledgement must not look like a failure." },
    'open.remote_list': { title: "List mirrored remote files", group: 'open', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "A mirror nobody can see is a copy of somebody's file sitting on disk with no way to tell where it came from or to get rid of it." },
    'open.resolve': { title: "Resolve a recognised path", group: 'open', kind: 'query', role: 'operator', effects: ['reads_fs'], doc: "A path resolved against the wrong root opens somebody else's file, so the root that was used is part of the answer and anything escaping every root is refused rather than clamped." },
    'open.rules_list': { title: "List recognition rules", group: 'open', kind: 'query', role: 'viewer', effects: [], doc: "A recognition system nobody can enumerate is one where `why did that not become a link` has no answer short of reading the source." },
    'open.rules_test': { title: "Test a line against the rules", group: 'open', kind: 'query', role: 'viewer', effects: [], doc: "Powers the config editor's live preview. Names the rule that fired, because a preview that only says whether something matched cannot help fix one that did not." },
    'pane.close': { title: "Close a pane", group: 'pane', kind: 'command', role: 'operator', effects: [], doc: "Close a pane. The session it showed keeps running — closing a view of something is not ending it." },
    'pane.focus': { title: "Focus a pane", group: 'pane', kind: 'command', role: 'operator', effects: [], doc: "Move focus to a pane, which is where typing goes. Focusing a pane that is not there is refused rather than silently ignored." },
    'pane.list': { title: "List panes", group: 'pane', kind: 'query', role: 'viewer', effects: [], doc: "Panes in a workspace's primary view, which one has focus, and how many fit on a standard terminal." },
    'pane.navigate': { title: "Move focus in a direction", group: 'pane', kind: 'query', role: 'viewer', effects: [], doc: "Geometric, over the placed rectangles rather than tree order — tree order gives wrong answers in asymmetric layouts. Deterministic, because breaking ties by recency makes the same keypress do two different things for reasons the user cannot see." },
    'pane.open': { title: "Open a pane", group: 'pane', kind: 'command', role: 'operator', effects: [], doc: "Open a pane onto an existing session. Presentation only: no process is started and none is stopped." },
    'plugin.enable': { title: "Enable a plugin", group: 'plugin', kind: 'command', role: 'admin', effects: [], doc: "Switch a plugin on or off. Idempotent: setting the state it already has is not an error." },
    'plugin.install': { title: "Install a plugin", group: 'plugin', kind: 'command', role: 'admin', effects: ['spawns_process'], doc: "Install a plugin with an explicit grant. What it asks for and what it receives are separate, and what was refused is reported." },
    'plugin.list': { title: "List plugins", group: 'plugin', kind: 'query', role: 'viewer', effects: [], doc: "Installed plugins with what each was granted, and which of those grants are high-consequence." },
    'plugin.start': { title: "Start a plugin", group: 'plugin', kind: 'command', role: 'admin', effects: ['spawns_process'], doc: "Run a plugin, handing it a socket and a token whose role comes from what it was granted. A plugin reaches omt through the same capability surface as any other client — there is no second API." },
    'presence.list': { title: "Who is connected", group: 'presence', kind: 'query', role: 'viewer', effects: [], doc: "Every client connected right now. \"Is somebody else looking at this\" is a question people ask before they type, and a terminal that cannot answer it is one where two people interleave keystrokes into one shell." },
    'queue.edit': { title: "Edit a queued message", group: 'queue', kind: 'command', role: 'operator', effects: [], doc: "Unsupported on an agent's own queue, which emits enqueue and remove and no third verb. The pair is not a substitute: the removal is the unconfirmable half." },
    'queue.enqueue': { title: "Queue a message", group: 'queue', kind: 'command', role: 'operator', effects: ['writes_pty'], doc: "Takes a binding rather than a session. A replayed enqueue against a session whose agent has exited types the text into a shell prompt, where it runs as a command." },
    'queue.list': { title: "List the queue", group: 'queue', kind: 'query', role: 'viewer', effects: [], doc: "Reports `unknown` when the reader is stale or has never spoken. An empty queue is a claim, and a broken reader must not be able to make it." },
    'queue.remove': { title: "Remove a queued message", group: 'queue', kind: 'command', role: 'operator', effects: ['writes_pty'], doc: "Never retried automatically: a repeated removal against a queue that has since drained removes a different message." },
    'queue.reorder': { title: "Reorder the queue", group: 'queue', kind: 'command', role: 'operator', effects: [], doc: "This is what a client's queue-reorder check asks for. Unsupported on an agent's own queue, and the client hides the drag handles rather than disabling them." },
    'recall.policy': { title: "What is indexed", group: 'recall', kind: 'query', role: 'viewer', effects: [], doc: "A search index nobody can enumerate is one nobody can reason about. Reasoning is excluded by default: it is the most privacy-sensitive text an agent produces." },
    'recall.record': { title: "Record a command", group: 'recall', kind: 'command', role: 'operator', effects: [], doc: "Add a command to the history that suggestions are drawn from." },
    'recall.suggest': { title: "Suggest a command", group: 'recall', kind: 'query', role: 'viewer', effects: [], doc: "Commands from history matching a prefix, scored by use in this workspace. Destructive commands are never suggested." },
    'remote.probe': { title: "Probe a host", group: 'remote', kind: 'query', role: 'operator', effects: ['network'], doc: "Operator, not Viewer, because it makes this machine reach out to a host the caller chose. Viewer with NETWORK has no carve-out." },
    'search.explain': { title: "Why this result ranked here", group: 'search', kind: 'query', role: 'viewer', effects: [], doc: "A transparent weighted product with no learning and no hidden state. Search over somebody's own history is where a wrong answer looks exactly like a right one, and a ranker that cannot explain itself gives them no way to notice." },
    'search.session': { title: "Search a session", group: 'search', kind: 'query', role: 'viewer', effects: [], doc: "Find text across a session's screen and history, with the row and offsets of each hit so a client can scroll to it and highlight exactly that span." },
    'security.bind_check': { title: "Check a listen configuration", group: 'security', kind: 'query', role: 'admin', effects: [], doc: "A misconfiguration fails the daemon rather than warning. A warning about an open port is printed once, into a log nobody reads, on a machine that is now reachable from the network." },
    'security.publish_check': { title: "Check before publishing", group: 'security', kind: 'query', role: 'admin', effects: [], doc: "Funnel puts the instance on the open internet, and the difference between that and a tailnet is not visible in any configuration omt reads. Somebody who enabled it for a demo and forgot is who this is for." },
    'session.acquire': { title: "Take the writer token", group: 'session', kind: 'command', role: 'operator', effects: [], doc: "Take the writer token for a session, returning the epoch every write is checked against." },
    'session.blocks': { title: "List command blocks", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "Commands run in a session with their output ranges and exit codes, from OSC 133. A shell that emits no marks reports none rather than guesses." },
    'session.capture': { title: "Capture scrollback", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "The thing every migrating script asks for first. Reports the total as well as what it returned, so a truncated capture is visible rather than looking complete." },
    'session.close': { title: "Close a session", group: 'session', kind: 'command', role: 'operator', effects: ['destructive'], doc: "End a session and stop the process on it. Idempotent." },
    'session.create': { title: "Start a session", group: 'session', kind: 'command', role: 'operator', effects: ['spawns_process'], doc: "Start a session in a workspace, running a program on a pty. Deduplicated by intent id, so a reconnect retry does not start a second process." },
    'session.list': { title: "List sessions", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "Every session this instance holds, optionally filtered to one workspace." },
    'session.read': { title: "Read a session", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "The visible screen as text, optionally with scrollback." },
    'session.release': { title: "Give up the writer token", group: 'session', kind: 'command', role: 'operator', effects: [], doc: "Give up the writer token. Idempotent: releasing one you do not hold is not an error." },
    'session.rename': { title: "Rename a session", group: 'session', kind: 'command', role: 'operator', effects: [], doc: "A roster of six things called `shell` is what omt shows without this. Detection answers it for agents; for everything else the answer is letting somebody say what a thing is." },
    'session.resize': { title: "Resize a session", group: 'session', kind: 'command', role: 'operator', effects: ['writes_pty'], doc: "Resize a session. The grid and the kernel are told together, so a program is never handed a size the kernel disagrees with." },
    'session.restart': { title: "Restart a session", group: 'session', kind: 'command', role: 'operator', effects: ['spawns_process'], doc: "Respawn the command behind a session restored from a snapshot, keeping the old output above a separator." },
    'session.scrollback': { title: "Read scrollback", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "History as styled lines, by absolute row. Structured rather than raw bytes, so a browser needs no second terminal emulator to show what scrolled past." },
    'session.snapshot': { title: "Snapshot a session", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "The visible screen as styled runs, so a remote client renders the same picture as the terminal without emulating one." },
    'session.timeline': { title: "What happened here", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "Derived from the event log, so it can be rebuilt at any time. Only consecutive identical calls collapse, and the canonicaliser strips whitespace and nothing else — one that ignored arguments would collapse `rm -rf build` and `rm -rf /`." },
    'session.transcript': { title: "Read an agent transcript", group: 'session', kind: 'query', role: 'viewer', effects: [], doc: "Messages, reasoning, tool calls and results for an agent session. An agent emits no command marks, so blocks do not apply to it; this is what it is read through instead." },
    'session.write': { title: "Type into a session", group: 'session', kind: 'command', role: 'operator', effects: ['writes_pty'], doc: "Write input to a session, gated on the writer token's epoch." },
    'setup.detect_agents': { title: "Find installed agents", group: 'setup', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "Every agent omt can drive, found or not. Listing only what is present hides the difference between an agent omt did not find and one it has never heard of." },
    'shell.integration': { title: "Shell integration status", group: 'shell', kind: 'query', role: 'viewer', effects: [], doc: "Whether the shell emits command marks, judged by what has been seen rather than by a setting, with the line that enables them. omt prints it and never edits a shell's configuration itself." },
    'ssh.plan': { title: "Preview an omt ssh session", group: 'ssh', kind: 'query', role: 'operator', effects: [], doc: "An argument vector, never a shell string: a hostname from a config file with a quote in it would otherwise become remote execution." },
    'state.restore': { title: "Restore instance state", group: 'state', kind: 'command', role: 'operator', effects: [], doc: "Reopen the workspaces from a snapshot, reporting any whose directory is gone rather than dropping them silently." },
    'state.save': { title: "Save instance state", group: 'state', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Write the open workspaces to a snapshot a later run can restore. Written atomically: a crash mid-write leaves the previous snapshot, never half of a new one." },
    'store.migrate_status': { title: "Can this store be opened", group: 'store', kind: 'query', role: 'admin', effects: ['reads_fs'], doc: "There is no best-effort partial parse. A partial read of a newer format silently drops whatever that version added, and writes the store back without it." },
    'store.paths': { title: "What omt writes down", group: 'store', kind: 'query', role: 'operator', effects: [], doc: "The alternative to this list is finding out what omt persists by reading twelve crates, which nobody does — least of all somebody deciding whether to run it on a work machine." },
    'store.redaction_test': { title: "Try the redactor", group: 'store', kind: 'query', role: 'operator', effects: [], doc: "So somebody can find out what the detector catches before trusting it with something, rather than after." },
    'store.retention': { title: "What happens to this data", group: 'store', kind: 'query', role: 'viewer', effects: [], doc: "Compact first, delete second. The output of a build from three months ago is worthless; the fact that you ran it, where, and that it failed, is still useful and costs two hundred bytes." },
    'task.cancel': { title: "Cancel an operation", group: 'task', kind: 'command', role: 'operator', effects: [], doc: "Cooperative: it stops at its next checkpoint. One past its point of no return refuses with the reason rather than reporting a success it cannot deliver." },
    'task.get': { title: "Get a running operation", group: 'task', kind: 'query', role: 'viewer', effects: [], doc: "Where one operation got to, so a client that reconnected mid-job learns the answer it can no longer hear." },
    'task.list': { title: "List running operations", group: 'task', kind: 'query', role: 'viewer', effects: [], doc: "22 §10.1's job registry. Named `task` because `job` already means a scheduled job, and one name for two things would resolve by load order." },
    'term.profile': { title: "Check this terminal", group: 'term', kind: 'query', role: 'viewer', effects: ['reads_fs'], doc: "A wrong TERM does not fail; it draws a subtly wrong screen that people blame on omt for weeks. This says what is advertised, what was observed, and where they disagree." },
    'theme.get': { title: "Read the theme", group: 'theme', kind: 'query', role: 'viewer', effects: [], doc: "The colours in force, so a remote client renders a session in the user's own theme rather than in its own defaults." },
    'uninstall.apply': { title: "Uninstall omt", group: 'uninstall', kind: 'command', role: 'admin', effects: ['destructive', 'writes_fs'], doc: "Refuses unless it is given the hash of a plan that still matches the disk. A confirmation against a plan that has since changed is a confirmation of something the user never saw." },
    'uninstall.plan': { title: "Preview an uninstall", group: 'uninstall', kind: 'query', role: 'admin', effects: ['reads_fs'], doc: "Driven by the setup manifest. Anything absent from it is never touched — an uninstall that reasons about what it probably wrote eventually removes somebody else's configuration." },
    'upgrade.check': { title: "Check for an upgrade", group: 'upgrade', kind: 'query', role: 'operator', effects: ['network'], doc: "omt never checks on its own. This reaches the network because the user typed it, and reports who owns the binary so a package manager's file is delegated to rather than overwritten." },
    'usage.report': { title: "Usage and quota", group: 'usage', kind: 'query', role: 'viewer', effects: [], doc: "Tokens spent per session and in total, with whatever the agent said about its rate limit. Cost appears only when the agent stated one — omt never computes it from a price table of its own." },
    'voice.append': { title: "Add dictated text", group: 'voice', kind: 'command', role: 'operator', effects: [], doc: "Append a transcript chunk to a session's dictation buffer. Partial chunks are replaced by later ones; only the settled part is offered for sending." },
    'voice.clear': { title: "Clear dictation", group: 'voice', kind: 'command', role: 'operator', effects: [], doc: "Discard a session's dictation buffer. Idempotent." },
    'voice.providers': { title: "List speech engines", group: 'voice', kind: 'query', role: 'viewer', effects: [], doc: "Speech-to-text engines this instance can use, and whether each has a key. Presence only — a capability that returned a key would put it in the first log somebody captured." },
    'workspace.list': { title: "List workspaces", group: 'workspace', kind: 'query', role: 'viewer', effects: [], doc: "Every workspace this instance has open, with its session count." },
    'workspace.open': { title: "Open a workspace", group: 'workspace', kind: 'command', role: 'operator', effects: [], doc: "Open a workspace at a canonical path. Idempotent: the id is derived from the path." },
    'worktree.add': { title: "Add a worktree", group: 'worktree', kind: 'command', role: 'operator', effects: ['writes_fs'], doc: "Create a git worktree, which becomes a workspace by the id its path derives. Additive: it touches nothing that already exists, and a path already in use is refused rather than overwritten." },
    'worktree.list': { title: "List worktrees", group: 'worktree', kind: 'query', role: 'viewer', effects: [], doc: "Every worktree of a workspace's repository, with the workspace id each would open as. Read from git rather than from omt's own records, so it cannot disagree with reality." },
    'worktree.remove': { title: "Remove a worktree", group: 'worktree', kind: 'command', role: 'operator', effects: ['destructive'], doc: "Remove a worktree. Refused when it has uncommitted changes unless force is given — an agent's output is usually why the worktree was wanted, and deleting it on a tap is unrecoverable." },
};
